hub['body']+='<h2>Topics in this track</h2><ul>'+''.join('<li>'+link('web-tech/'+topic['slug'])+' — '+html.escape(topic['summary'])+'</li>' for topic in topics)+'</ul>'
hub['body']+='<h2>Prerequisite paths</h2><p>'+'; '.join(link(path) for path in ['web-tech/sse-and-websocket-choice','web-tech/live-update-reconnect-and-order','web-tech/authorization-and-tenant-boundaries'])+'.</p>'
